'use strict';
/* SIPETAK workflow: local-first encrypted data, editable INTERNAL SLA, Web Notifications,
   optional HTTPS self-hosted encrypted sync and Web Push. No official approvals. */
const WF_SLA_DEFAULTS={
  'Disposisi Sekwan':{hours:4,explain:'Respons awal disposisi; usulan internal'},
  'Bahan briefing Sekwan':{hours:4,explain:'Bahan briefing, sebelum agenda jika diketahui'},
  'Bahan Persidangan':{hours:8,explain:'Satu hari kerja sebelum rapat; usulan internal'},
  'Konsep Risalah':{hours:16,explain:'Dua hari kerja setelah rapat; usulan internal'},
  'Matriks DIM':{hours:24,explain:'Tiga hari kerja; usulan internal'},
  'Tindak lanjut rapat':{hours:24,explain:'Tiga hari kerja; usulan internal'},
  'Telaahan Kebijakan':{hours:16,explain:'Dua hari kerja; usulan internal'}
};
const WF_WARNINGS=[{name:'24 jam',minutes:1440},{name:'3 jam',minutes:180},{name:'30 menit',minutes:30},{name:'jatuh tempo',minutes:0}];
let wfTimer=null,wfAudio=null,wfCloudTimer=null,wfSyncRunning=false,wfSoundReady=false,wfLastSyncTime=0;
function ensureWorkflow(){
 if(!data)return;
 for(const key of ['directives','meetings','dims','laws','audit','notifyHistory'])if(!Array.isArray(data[key]))data[key]=[];
 if(!data.wfSettings||typeof data.wfSettings!=='object')data.wfSettings={};
 if(!data.wfSettings.slaRules)data.wfSettings.slaRules=Object.fromEntries(Object.entries(WF_SLA_DEFAULTS).map(([k,v])=>[k,v.hours]));
 if(!data.wfSettings.notify)data.wfSettings.notify={sound:false,system:false,minutes:[1440,180,30,0]};
 if(!data.wfSettings.cloud)data.wfSettings.cloud={url:'',token:'',enabled:false,auto:false,push:false,deviceId:'',lastSync:null};
 if(!data.wfSettings.cloud.deviceId)data.wfSettings.cloud.deviceId='DEV-'+crypto.randomUUID();
 if(!data.wfSettings.seededReferences){if(data.laws.length===0)data.laws.push(
 {id:'LAW-REF-TATIB24',title:'Peraturan DPRD Kabupaten Kapuas Hulu tentang Tata Tertib DPRD',type:'Peraturan DPRD',number:'1',year:'2024',article:'Pasal 125–126; 135–138',status:'Perlu verifikasi',origin:'Dokumen Tata Tertib DPRD Tahun 2024 yang diunggah; cek versi berlaku di JDIH',verifiedAt:'',notes:'Jenis rapat, risalah dan pengambilan keputusan. Tidak otomatis menafsirkan keabsahan keputusan.'},
 {id:'LAW-REF-PERBUP57',title:'Kedudukan, Susunan Organisasi, Tugas dan Fungsi serta Tata Kerja Sekretariat DPRD',type:'Peraturan Bupati',number:'57',year:'2021',article:'Pasal 3–7; 11–12',status:'Perlu verifikasi',origin:'Dokumen Perbup Kapuas Hulu 57/2021 yang diunggah; cek peraturan perubahan',verifiedAt:'',notes:'Pembagian tugas Sekwan dan Bagian Persidangan & Perundang-undangan.'},
 {id:'LAW-REF-RENSTRA25',title:'Rancangan Akhir Renstra Sekretariat DPRD Kabupaten Kapuas Hulu 2025–2029',type:'Renstra',number:'',year:'2025',article:'Bab II–IV, Tabel 4.5',status:'Rancangan / belum final',origin:'Dokumen Rancangan Akhir Renstra 2025–2029 yang diunggah',verifiedAt:'',notes:'IKU dan target belum otomatis berlaku sebagai Renstra/IKU yang telah ditetapkan.'});data.wfSettings.seededReferences=true;}
}
function workflowIkiOptions(selected=''){return '<option value="">— Tanpa tautan IKI —</option>'+(KATALOG.iki_individu||[]).map(x=>`<option value="${txt(x.id)}" ${x.id===selected?'selected':''}>${txt(x.id+' · '+x.nama)}</option>`).join('');}
function wfStamp(date){const d=new Date(date);if(Number.isNaN(d.getTime()))return '';return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')+'T'+[d.getHours(),d.getMinutes()].map(x=>String(x).padStart(2,'0')).join(':');}
function wfFormat(dt){if(!dt)return '—';const date=new Date(dt);return Number.isFinite(date.getTime())?date.toLocaleString('id-ID',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';}
function wfFuture(date,delta){let d=new Date(date);d.setMinutes(d.getMinutes()+delta);return d;}
function wfBusinessHours(date,hours){let d=new Date(date),remaining=Math.round(Number(hours)*60),guard=0;
 if(Number.isNaN(d.getTime())||!Number.isFinite(remaining)||remaining<0||remaining>60000)return null;
 while(remaining>0&&guard++<6000){const day=d.getDay(),hh=d.getHours()+d.getMinutes()/60;if(day===0||day===6||hh>=16){d.setDate(d.getDate()+1);d.setHours(8,0,0,0);continue;}if(hh<8){d.setHours(8,0,0,0);continue;}const available=Math.round((16-hh)*60);const step=Math.min(remaining,available);d.setMinutes(d.getMinutes()+step);remaining-=step;}
 return remaining===0?d:null;
}
function wfSubtractBusinessHours(date,hours){let d=new Date(date),remaining=Math.round(Number(hours)*60),guard=0;if(Number.isNaN(d.getTime())||remaining<0||remaining>60000)return null;
 while(remaining>0&&guard++<6000){const day=d.getDay(),hh=d.getHours()+d.getMinutes()/60;if(day===0||day===6||hh<=8){d.setDate(d.getDate()-1);d.setHours(16,0,0,0);continue;}if(hh>16){d.setHours(16,0,0,0);continue;}const available=Math.round((hh-8)*60);const step=Math.min(remaining,available);d.setMinutes(d.getMinutes()-step);remaining-=step;}return remaining===0?d:null;}
function wfSetDue(type,source){const h=data.wfSettings.slaRules[type]??WF_SLA_DEFAULTS[type]?.hours??8;return wfStamp(wfBusinessHours(source||new Date(),h));}
function wfAudit(kind,verb,record){data.audit.unshift({id:uid('LOG'),at:isoNow(),type:kind,action:verb,objectId:record.id,title:record.title||'',source:'Catatan pengguna'});if(data.audit.length>250)data.audit.length=250;}
function wfAllDeadlines(){ensureWorkflow();const out=[];
 data.tasks.filter(t=>t.status!=='Selesai').forEach(t=>{const when=t.deadlineAt||(t.deadline?t.deadline+'T16:00':'');if(when)out.push({id:'t-'+t.id,title:t.title,role:/Sekwan|Sekretaris/.test(t.category||'')?'Asisten Sekwan':'Penelaah',kind:'Tugas',dueAt:when,priority:t.priority||'Normal',reference:t.id});});
 data.directives.filter(x=>x.status!=='Selesai'&&x.status!=='Dibatalkan').forEach(x=>out.push({id:'d-'+x.id,title:x.title,role:'Asisten Sekwan',kind:'Disposisi',dueAt:x.dueAt,priority:x.priority||'Normal',reference:x.id}));
 data.meetings.forEach(x=>{
  if(x.prepStatus!=='Selesai'&&x.prepDueAt)out.push({id:'m-prep-'+x.id,title:'Bahan: '+x.title,role:'Penelaah',kind:'Bahan rapat',dueAt:x.prepDueAt,priority:x.priority||'Normal',reference:x.id});
  if(x.minutesStatus!=='Selesai'&&x.minutesDueAt&&x.meetingAt&&Date.now()>=Date.parse(x.meetingAt)-86400000)out.push({id:'m-min-'+x.id,title:'Risalah: '+x.title,role:'Penelaah',kind:'Risalah',dueAt:x.minutesDueAt,priority:x.priority||'Normal',reference:x.id});
 });
 data.dims.filter(x=>x.status!=='Selesai').forEach(x=>{if(x.dueAt)out.push({id:'dim-'+x.id,title:'DIM: '+x.title,role:'Penelaah',kind:'DIM',dueAt:x.dueAt,priority:x.priority||'Normal',reference:x.id});});
 return out.filter(x=>{const rec=[...data.tasks,...data.directives,...data.meetings,...data.dims].find(v=>v.id===x.reference);return rec&&!myYearArchived(myYearOf(rec,MY_COLLECTIONS.find(k=>data[k]?.includes(rec))||'tasks'));}).filter(x=>x.dueAt&&Number.isFinite(new Date(x.dueAt).getTime())).sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt));
}
function wfSlaState(x,now=Date.now()){const diff=Date.parse(x.dueAt)-now;if(diff<0)return {label:'Terlambat',className:'wf-over',diff};if(diff<=30*60000)return {label:'≤30 menit',className:'wf-over',diff};if(diff<=3*3600000)return {label:'≤3 jam',className:'wf-soon',diff};if(diff<=86400000)return {label:'≤24 jam',className:'wf-warn',diff};return {label:'Terjadwal',className:'wf-ok',diff};}
function wfDeadlineRows(limit=50){const rows=wfActiveDeadlines().slice(0,limit);return rows.length?rows.map(x=>{const state=wfSlaState(x);return `<div class="wf-deadline ${state.className}"><div><b>${txt(x.title)}</b><p>${txt(x.kind)} · ${txt(x.role)} · ${txt(x.priority)} · ${wfFormat(x.dueAt)}</p></div><span class="wf-pill ${state.className}">${txt(state.label)}</span></div>`}).join(''):blank('Belum ada tenggat aktif. Tetapkan tanggal dan jam pada tugas atau disposisi.','◷');}
function wfActiveDeadlines(){return wfAllDeadlines().filter(x=>{const rec=[...data.tasks,...data.directives,...data.meetings,...data.dims].find(v=>v.id===x.reference);return rec&&myYearOf(rec,MY_COLLECTIONS.find(k=>data[k]?.includes(rec))||'tasks')===myActiveYear()});}
function wfDashboard(){if(!data)return '';const deadlines=wfActiveDeadlines();const overdue=deadlines.filter(x=>Date.parse(x.dueAt)<Date.now()).length,soon=deadlines.filter(x=>{const diff=Date.parse(x.dueAt)-Date.now();return diff>=0&&diff<=86400000}).length;return `<section class="card wf-focus"><div class="section-head"><div><h3>◷ Pusat Tenggat & SLA</h3><p>Pantauan langsung tugas utama dan asistensi Sekwan · zona waktu perangkat</p></div><button class="btn sm secondary" data-action="navigate" data-view="sla">Buka pusat pengingat →</button></div><div class="wf-summary"><div><strong>${deadlines.length}</strong><small>Tenggat aktif</small></div><div><strong>${soon}</strong><small>Dalam 24 jam</small></div><div><strong>${overdue}</strong><small>Lewat tenggat</small></div></div><div class="wf-scroll">${wfDeadlineRows(4)}</div></section>`;}
function wfSettingsBanner(){return `<div class="callout warn"><b>Pengingat SLA:</b> Bunyi lokal hanya berfungsi ketika SIPETAK terbuka dan bunyi sudah diaktifkan. Notifikasi iPhone saat aplikasi ditutup memerlukan Web Push pada HTTPS dari server yang dikonfigurasi; alternatifnya ekspor kalender dengan alarm. <button type="button" class="btn sm ghost" data-action="navigate" data-view="sla">Pengaturan pengingat</button></div>`;}
function wfTinyStatus(s){return `<span class="tag ${s==='Selesai'?'':s==='Proses'?'amber':'gray'}">${txt(s||'Rencana')}</span>`;}
function wfWorkflowOptions(value){const all=[...data.directives.map(x=>({...x,title:'Sekwan: '+x.title})),...data.meetings.map(x=>({...x,title:'Rapat: '+x.title})),...data.dims.map(x=>({...x,title:'DIM: '+x.title}))];return wfGeneralOptions(all,value,'— Tanpa pekerjaan tambahan —');}
function wfGeneralOptions(arr,val,empty){return `<option value="">${txt(empty)}</option>`+arr.map(x=>`<option value="${txt(x.id)}" ${x.id===val?'selected':''}>${txt(x.title||x.rumusan_hasil||x.id)}</option>`).join('');}
function wfCategorySelect(items,current){return items.map(x=>`<option value="${txt(x)}" ${x===current?'selected':''}>${txt(x)}</option>`).join('');}
function sekretarisPage(){const rows=myItems('directives').slice().sort((a,b)=>(a.status==='Selesai'?1:-1)-(b.status==='Selesai'?1:-1)||Date.parse(a.dueAt)-Date.parse(b.dueAt));return `<div class="section-head"><div><h3>Penugasan & asistensi Sekretaris DPRD</h3><p>Pantau arahan, agenda, bahan briefing, koordinasi dan tindak lanjut.</p></div><button class="btn" data-action="wf-new" data-kind="directive">＋ Disposisi / Agenda</button></div><div class="callout warn">Ruang ini mencatat <b>penugasan tambahan</b>. Tidak memberikan kewenangan persetujuan, representasi atau tanda tangan Sekwan tanpa dasar resmi.</div><div class="wf-cards">${rows.length?rows.map(x=>`<article class="card"><div class="wf-card-head">${wfTinyStatus(x.status)} <span class="tiny muted">${txt(x.type||'Disposisi Sekwan')}</span></div><h3>${txt(x.title)}</h3><p class="muted">Sumber: ${txt(x.source||'Belum dicatat')}<br>Koordinasi: ${txt(x.person||'—')}<br>Output: ${txt(x.output||'—')}</p><div class="wf-card-foot"><span class="wf-pill ${wfSlaState(x).className}">${wfFormat(x.dueAt)}</span><div class="actions"><button class="btn sm secondary" data-action="wf-brief" data-id="${txt(x.id)}">Briefing</button><button class="btn sm ghost" data-action="wf-edit" data-kind="directive" data-id="${txt(x.id)}">Ubah</button><button class="btn sm danger" data-action="wf-delete" data-kind="directive" data-id="${txt(x.id)}">Hapus</button></div></div></article>`).join(''):blank('Belum ada disposisi atau agenda Sekwan. Gunakan tambah untuk mulai.','♧')}</div>`;}
function persidanganPage(){const items=myItems('meetings').slice().sort((a,b)=>Date.parse(a.meetingAt)-Date.parse(b.meetingAt));return `<div class="section-head"><div><h3>Agenda, berkas rapat, risalah & keputusan</h3><p>Ikuti siklus pra-rapat → rapat → risalah → tindak lanjut.</p></div><button class="btn" data-action="wf-new" data-kind="meeting">＋ Agenda Rapat</button></div><div class="callout">Referensi: Tata Tertib DPRD Nomor 1/2024 Pasal 125–126 (jenis rapat dan risalah) serta Pasal 135–138 (keputusan). Pencatatan bukan pengesahan risalah atau keputusan.</div><div class="wf-cards">${items.length?items.map(x=>`<article class="card"><div class="tiny muted">${txt(x.type||'Rapat DPRD')} · ${wfFormat(x.meetingAt)}</div><h3>${txt(x.title)}</h3><p class="muted">Lokasi: ${txt(x.place||'—')} · Dasar agenda: ${txt(x.source||'—')}</p><div class="wf-milestones"><span>Bahan rapat ${wfTinyStatus(x.prepStatus)}</span><span>Risalah ${wfTinyStatus(x.minutesStatus)}</span></div><p class="hint">Bahan: ${wfFormat(x.prepDueAt)} · Risalah: ${wfFormat(x.minutesDueAt)}</p><p>${txt(x.result||'Hasil dan tindak lanjut belum diisi').slice(0,200)}</p><div class="actions"><button class="btn sm secondary" data-action="wf-minutes" data-id="${txt(x.id)}">Cetak konsep rapat</button><button class="btn sm ghost" data-action="wf-edit" data-kind="meeting" data-id="${txt(x.id)}">Ubah</button><button class="btn sm danger" data-action="wf-delete" data-kind="meeting" data-id="${txt(x.id)}">Hapus</button></div></article>`).join(''):blank('Belum ada agenda persidangan.','▤')}</div>`;}
function raperdaPage(){const rows=myItems('dims').slice().sort((a,b)=>(a.perda||'').localeCompare(b.perda||'')||String(a.article||'').localeCompare(String(b.article||'')));return `<div class="section-head"><div><h3>Matriks Daftar Inventarisasi Masalah (DIM)</h3><p>Telusuri Raperda, pasal, rumusan, analisis, dan rekomendasi.</p></div><button class="btn" data-action="wf-new" data-kind="dim">＋ Tambah Baris DIM</button></div><div class="callout warn">DIM ini adalah catatan kerja. Hasil rapat dan perubahan pasal harus diverifikasi berdasarkan dokumen resmi dan pejabat berwenang.</div><div class="card table-scroller"><table class="data-table"><thead><tr><th>Raperda / Pasal</th><th>Masalah dan usulan</th><th>Dasar hukum</th><th>Status / SLA</th><th>Aksi</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td class="wrap"><b>${txt(x.perda)}</b><br>${txt(x.article)}</td><td class="wrap">${txt(x.title)}<div class="subline">${txt(x.proposal||'—').slice(0,170)}</div></td><td class="wrap">${txt(x.law||'—').slice(0,150)}</td><td>${wfTinyStatus(x.status)}<div class="tiny muted">${wfFormat(x.dueAt)}</div></td><td><div class="actions"><button class="btn sm ghost" data-action="wf-edit" data-kind="dim" data-id="${txt(x.id)}">Ubah</button><button class="btn sm danger" data-action="wf-delete" data-kind="dim" data-id="${txt(x.id)}">Hapus</button></div></td></tr>`).join(''):'<tr><td colspan="5">Belum ada data DIM.</td></tr>'}</tbody></table></div><div class="actions" style="margin-top:12px"><button class="btn secondary" data-action="wf-dimcsv">↓ Ekspor DIM CSV</button><button class="btn ghost" data-action="wf-dimprint">Cetak / PDF</button></div>`;}
function wfIkiTable(){const all=KATALOG.iki_individu||[];return `<div class="table-scroller"><table class="data-table"><thead><tr><th>IKI usulan</th><th>Target tahun ${myActiveYear()}</th><th>Tugas tertaut</th><th>Bukti tertaut</th></tr></thead><tbody>${all.map(x=>{const tasks=myItems('tasks').filter(t=>t.ikiId===x.id),others=[...myItems('directives'),...myItems('meetings'),...myItems('dims')].filter(t=>t.ikiId===x.id),ids=new Set(tasks.map(t=>t.id)),otherIds=new Set(others.map(t=>t.id));const ev=myItems('evidence').filter(b=>ids.has(b.taskId)||otherIds.has(b.workflowRefId));return `<tr><td class="wrap"><b>${txt(x.id)}</b><br>${txt(x.nama)}</td><td>${txt(data.ikiTargets.find(t=>t.ikiId===x.id&&t.year===myActiveYear())?.target||'Belum ditetapkan')}</td><td>${tasks.length+others.length}</td><td>${ev.length}</td></tr>`}).join('')}</tbody></table></div><p class="hint">Angka tugas/bukti adalah pemantauan kelengkapan, <b>bukan nilai kinerja resmi</b>. Persentase IKI memerlukan definisi pembilang, penyebut, bukti yang sah dan konfirmasi atasan.</p>`;}
function slaPage(){const active=wfActiveDeadlines(),n=data.wfSettings.notify,rate=wfCompletionRate();return `<div class="section-head"><div><h3>Prioritas dan tenggat kerja</h3><p>Semua SLA contoh dapat diubah. Bukan ketentuan hukum atau SKP resmi.</p></div><div class="actions"><button class="btn secondary" data-action="wf-calendar">↓ Pengingat Kalender (.ics)</button><button class="btn" data-action="wf-enable-notify">♬ Aktifkan bunyi & notifikasi</button></div></div><div class="wf-summary big"><div><strong>${active.length}</strong><small>Aktif</small></div><div><strong>${active.filter(x=>wfSlaState(x).label==='Terlambat').length}</strong><small>Terlambat</small></div><div><strong>${active.filter(x=>wfSlaState(x).diff>=0&&wfSlaState(x).diff<=3*3600000).length}</strong><small>≤3 jam</small></div></div><div class="callout">Ketepatan SLA internal dari catatan selesai: <b>${rate.done?rate.onTime+'/'+rate.done+' ('+rate.pct+'%)':'belum ada data selesai'}</b>. Hanya untuk pemantauan, bukan penilaian SKP resmi.</div><div class="split2"><section class="card"><h3>Daftar tenggat</h3><div class="wf-scroll">${wfDeadlineRows(70)}</div></section><section class="card"><h3>SLA operasional usulan</h3><p class="hint">Perhitungan jam kerja Senin–Jumat, pukul 08.00–16.00 waktu perangkat, <b>belum memperhitungkan hari libur/cuti</b>. Tetapkan tenggat resmi secara manual bila berbeda.</p>${Object.entries(WF_SLA_DEFAULTS).map(([name,s])=>`<div class="info-row"><span>${txt(name)}</span><b>${Number(data.wfSettings.slaRules[name]??s.hours)} jam kerja</b></div>`).join('')}<div class="actions" style="margin-top:16px"><button class="btn secondary" data-action="wf-edit-sla">Ubah SLA</button></div></section></div><div class="split2"><section class="card"><h3>Bunyi dan notifikasi</h3><p class="hint">Izin browser: <b>${typeof Notification==='undefined'?'tidak didukung':txt(Notification.permission)}</b>. Bunyi saat aplikasi terbuka: <b>${wfSoundReady?'siap sesi ini':(n.sound?'perlu diaktifkan ulang sesi ini':'belum diaktifkan')}</b>.</p><div class="actions"><button class="btn secondary" data-action="wf-test-sound">♪ Uji bunyi</button><button class="btn ghost" data-action="wf-enable-notify">Izinkan notifikasi</button></div><p class="hint">Untuk iPhone saat aplikasi tertutup dibutuhkan server Web Push. Bunyi push dikendalikan pengaturan iOS/macOS (Mode Fokus, volume, izin notifikasi).</p></section><section class="card"><h3>Pengingat iPhone & Mac via Kalender</h3><p class="hint">Ekspor .ics berisi pengingat 24 jam, 3 jam, 30 menit, dan saat tenggat. Impor ke Kalender perangkat; notifikasi/alarm berasal dari aplikasi Kalender meskipun SIPETAK ditutup.</p><div class="callout warn">Demi privasi, nama pekerjaan disamarkan menjadi “Pengingat pekerjaan SIPETAK”. Impor ke iCloud Calendar berarti metadata jadwal mungkin disinkronkan oleh layanan Kalender.</div><button class="btn" data-action="wf-calendar">Ekspor kalender privat</button></section></div><section class="card"><h3>Ringkasan IKI dan bukti yang tertaut</h3>${wfIkiTable()}</section>`;}
function sinkronPage(){const c=data.wfSettings.cloud;return `<div class="section-head"><div><h3>Sinkronisasi self-hosted & push (opsional)</h3><p>Opsi lama: perlu server HTTPS terpisah. Untuk database dan login Supabase, gunakan menu Supabase.</p></div></div><div class="callout critical"><b>Belum aktif secara otomatis.</b> Anda perlu alamat backend HTTPS, token akses dari administrator, dan izin push setiap perangkat. Server menyimpan brankas <b>terenkripsi</b> dan jadwal push tanpa judul pekerjaan, tetapi server tetap mengetahui waktu pengingat, alamat IP saat terhubung dan endpoint push. Tidak ada izin untuk dokumen Terbatas/Rahasia yang dilonggarkan.</div><div class="split2"><section class="card"><h3>Koneksi server</h3><form id="wfCloudForm" class="form-grid"><div class="field span2"><label for="wfCloudUrl">Alamat server HTTPS</label><input id="wfCloudUrl" name="url" type="url" value="${txt(c.url||'')}" placeholder="https://sipetak.instansi.go.id"></div><div class="field span2"><label for="wfCloudToken">Token akses pribadi</label><input id="wfCloudToken" name="token" type="password" value="${txt(c.token||'')}" placeholder="Token dari admin server"></div><div class="field span2"><label><input style="width:auto;min-height:auto" type="checkbox" name="auto" ${c.auto?'checked':''}> Sinkronisasi otomatis saat aplikasi terbuka</label></div><div class="field span2"><button class="btn" type="submit">Simpan konfigurasi terenkripsi</button></div></form><div class="hint">Terakhir sinkron: ${c.lastSync?wfFormat(c.lastSync):'Belum pernah'}.</div></section><section class="card"><h3>Kendali sinkronisasi</h3><p class="hint">Mulai dari MacBook dengan “Kirim ke server”. Di iPhone, pulihkan cadangan yang berasal dari MacBook dahulu agar memiliki kunci yang sama, lalu pilih “Ambil dari server”. Konflik tidak akan ditimpa diam-diam.</p><div class="actions"><button class="btn secondary" data-action="wf-sync-push">↑ Kirim perubahan</button><button class="btn ghost" data-action="wf-sync-pull">↓ Ambil data server</button><button class="btn ghost" data-action="wf-sync-status">Cek versi server</button></div><p class="hint">Jika kedua perangkat diedit saat offline, buat cadangan masing-masing; perbedaan tidak digabung otomatis.</p></section></div><section class="card"><h3>Pengingat saat SIPETAK ditutup (Web Push)</h3><p>Di iPhone, pasang SIPETAK ke Layar Utama (iOS 16.4+) lalu buka ikon aplikasinya. Di MacBook, gunakan Safari yang mendukung Web Push dan aktifkan izin. Server harus menyala terus dan terhubung internet.</p><div class="actions"><button class="btn" data-action="wf-push-register">Aktifkan push perangkat ini</button><button class="btn secondary" data-action="wf-push-update">Perbarui jadwal ke server</button><button class="btn ghost" data-action="wf-push-unregister">Nonaktifkan push</button></div><div class="callout warn">Pesan push sengaja generik (“Ada pekerjaan mendekati tenggat”) sehingga judul disposisi/rapat tidak dikirim sebagai isi notifikasi. Waktu dan pengiriman tetap dapat diproses oleh penyedia push.</div></section>`;}
