 if(!myAllowWrite())return;ensureWorkflow();const refs={directive:data.directives,meeting:data.meetings,dim:data.dims},arr=refs[kind],obj=arr.find(x=>x.id===id)||{},editing=Boolean(id);if(editing&&!myAllowWrite(obj))return;let content='';
 const sel=(v,current)=>wfCategorySelect(v,current);const st=['Rencana','Proses','Selesai','Dibatalkan'];const rhkOptions=wfGeneralOptions(myItems('rhks'),obj.rhkId,'— Belum ditautkan —');
 if(kind==='directive')content=`<div class="form-grid">${field('Uraian penugasan','title','text',obj.title||'','Contoh: Menyiapkan briefing Sekwan',true,true)}${field('Jenis','type','select','','',false,false,sel(['Disposisi Sekwan','Bahan briefing Sekwan','Agenda Sekwan','Tindak lanjut rapat','Koordinasi'],obj.type||'Disposisi Sekwan'))}${field('Prioritas','priority','select','','',false,false,sel(['Normal','Tinggi','Mendesak'],obj.priority||'Normal'))}${field('Diterima tanggal/jam','receivedAt','datetime-local',obj.receivedAt||wfStamp(new Date()),'',true)}${field('Tenggat tanggal/jam','dueAt','datetime-local',obj.dueAt||wfSetDue(obj.type||'Disposisi Sekwan',obj.receivedAt||new Date()),'',true)}${field('Status','status','select','','',false,false,sel(st,obj.status||'Rencana'))}${field('Asal arahan / nomor disposisi','source','text',obj.source||'','Bukti penugasan yang sah',false,true)}${field('Koordinasi dengan','person','text',obj.person||'','Unit / petugas terkait',false,true)}${field('RHK terkait','rhkId','select','','',false,true,rhkOptions)}${field('IKI usulan terkait','ikiId','select','','',false,true,workflowIkiOptions(obj.ikiId))}${field('Output / hasil','output','textarea',obj.output||'','Tautan bahan briefing / catatan hasil',false,true)}${field('Catatan / tindak lanjut','notes','textarea',obj.notes||'','Uraian tindak lanjut',false,true)}</div>`;
 if(kind==='meeting')content=`<div class="form-grid">${field('Nama agenda rapat','title','text',obj.title||'','Contoh: Rapat Bapemperda tentang Raperda',true,true)}${field('Jenis rapat','type','select','','',false,false,sel(['Paripurna','Bamus','Bapemperda','Badan Anggaran','Komisi','Gabungan Komisi','Pansus','Badan Kehormatan','Rapat Dengar Pendapat','Lainnya'],obj.type||'Paripurna'))}${field('Waktu rapat','meetingAt','datetime-local',obj.meetingAt||wfStamp(wfFuture(new Date(),24*60)),'',true)}${field('Lokasi','place','text',obj.place||'','Ruang rapat / tempat',false)}${field('Tenggat bahan rapat','prepDueAt','datetime-local',obj.prepDueAt||wfStamp(wfSubtractBusinessHours(obj.meetingAt||wfFuture(new Date(),24*60),8)),'',true)}${field('Status bahan','prepStatus','select','','',false,false,sel(['Rencana','Proses','Selesai'],obj.prepStatus||'Rencana'))}${field('Tenggat konsep risalah','minutesDueAt','datetime-local',obj.minutesDueAt||wfStamp(wfBusinessHours(obj.meetingAt||wfFuture(new Date(),24*60),16)),'',true)}${field('Status risalah','minutesStatus','select','','',false,false,sel(['Rencana','Proses','Selesai'],obj.minutesStatus||'Rencana'))}${field('Dasar agenda','source','text',obj.source||'','Undangan / arahan / keputusan Bamus',false,true)}${field('RHK terkait','rhkId','select','','',false,true,rhkOptions)}${field('IKI usulan terkait','ikiId','select','','',false,true,workflowIkiOptions(obj.ikiId))}${field('Bahan dan ringkasan pembahasan','materials','textarea',obj.materials||'','Bahan, daftar hadir, catatan pokok pembahasan',false,true)}${field('Rumusan hasil / keputusan','result','textarea',obj.result||'','Rumusan yang masih perlu diverifikasi',false,true)}${field('Rencana tindak lanjut','followup','textarea',obj.followup||'','Penanggung jawab dan tenggat tindak lanjut',false,true)}</div>`;
 if(kind==='dim')content=`<div class="form-grid">${field('Judul masalah','title','text',obj.title||'','Pokok masalah dalam rancangan',true,true)}${field('Nama Raperda','perda','text',obj.perda||'','Raperda yang dibahas',true,true)}${field('Pasal / ayat','article','text',obj.article||'','Contoh: Pasal 5 ayat (1)',false)}${field('Tenggat telaah','dueAt','datetime-local',obj.dueAt||wfSetDue('Matriks DIM',new Date()),'',true)}${field('Status','status','select','','',false,false,sel(['Rencana','Proses','Selesai'],obj.status||'Rencana'))}${field('RHK terkait','rhkId','select','','',false,false,rhkOptions)}${field('IKI usulan terkait','ikiId','select','','',false,true,workflowIkiOptions(obj.ikiId))}${field('Rumusan saat ini','current','textarea',obj.current||'','Teks usulan pasal (cek sumber resmi)',false,true)}${field('Masalah / analisis','issue','textarea',obj.issue||'','Persoalan norma, kejelasan, implikasi',false,true)}${field('Usulan perubahan','proposal','textarea',obj.proposal||'','Rumusan alternatif',false,true)}${field('Dasar hukum / pasal','law','textarea',obj.law||'','Peraturan, pasal dan sumber',false,true)}${field('Hasil pembahasan','result','textarea',obj.result||'','Hasil resmi jika sudah diverifikasi',false,true)}</div>`;
 openModal((editing?'Ubah ':'Tambah ')+({directive:'Disposisi/Agenda Sekwan',meeting:'Agenda Rapat',dim:'Matriks DIM'}[kind]),'Seluruh data disimpan dalam brankas lokal terenkripsi.',content,null,'wfEntityForm');simplifyForm('wfEntityForm',({directive:['title','type','dueAt'],meeting:['title','type','meetingAt','place'],dim:['title','perda','article','dueAt']})[kind]||[],false);$('wfEntityForm').dataset.kind=kind;$('wfEntityForm').dataset.id=id;if(!editing&&kind==='meeting'){$('wfEntityForm').elements.meetingAt?.addEventListener('change',e=>{const dt=e.currentTarget.value;if(!dt)return;const before=wfSubtractBusinessHours(dt,8),after=wfBusinessHours(dt,16);if(before)$('wfEntityForm').elements.prepDueAt.value=wfStamp(before);if(after)$('wfEntityForm').elements.minutesDueAt.value=wfStamp(after);});}
 if(!editing&&kind==='directive'){$('wfEntityForm').elements.type?.addEventListener('change',e=>{const f=$('wfEntityForm');if(f.elements.dueAt)f.elements.dueAt.value=wfSetDue(e.currentTarget.value,f.elements.receivedAt?.value||new Date());});}
 $('wfEntityForm').addEventListener('submit',wfSaveEntity);
