async function wfSaveEntity(e){e.preventDefault();if(!myAllowWrite())return;const f=e.currentTarget,kind=f.dataset.kind,id=f.dataset.id,val=formValue(f),map={directive:data.directives,meeting:data.meetings,dim:data.dims},arr=map[kind],old=arr.find(x=>x.id===id);if(old&&!myAllowWrite(old))return;if(val.rhkId&&!myItems('rhks').some(r=>r.id===val.rhkId))return toast('RHK harus berasal dari tahun kinerja yang sama.',true);if(val.status==='Selesai'&&!String(val.output||val.result||'').trim()&&kind!=='meeting'){toast('Cantumkan output/hasil sebelum menandai selesai.',true);return;}if(kind==='directive'&&Date.parse(val.dueAt)<Date.parse(val.receivedAt)){toast('Tenggat tidak boleh sebelum diterima.',true);return;}if(kind==='meeting'&&Date.parse(val.minutesDueAt)<Date.parse(val.meetingAt)){toast('Tenggat risalah harus setelah waktu rapat.',true);return;}const row={...(old||{}),...val,id:old?.id||uid(({directive:'DSP',meeting:'RPT',dim:'DIM'})[kind]),createdAt:old?.createdAt||isoNow(),updatedAt:isoNow(),performanceYear:old?.performanceYear||myActiveYear()};if(kind==='meeting'){if(val.prepStatus==='Selesai'&&old?.prepStatus!=='Selesai')row.prepCompletedAt=isoNow();if(val.minutesStatus==='Selesai'&&old?.minutesStatus!=='Selesai')row.minutesCompletedAt=isoNow();if(val.prepStatus!=='Selesai')row.prepCompletedAt=null;if(val.minutesStatus!=='Selesai')row.minutesCompletedAt=null;}else{if(val.status==='Selesai'&&old?.status!=='Selesai')row.completedAt=isoNow();else if(val.status!=='Selesai')row.completedAt=null;}if(old)Object.assign(old,row);else arr.push(row);wfAudit(kind,old?'Diperbarui':'Dibuat',row);try{if(!old&&typeof lcAutoRegister==='function')await lcAutoRegister(kind,row);await queueSave();closeModal();render();toast('Pekerjaan tersimpan. Tenggat masuk pusat SLA.');}catch(ex){fail(ex)}}
async function wfDelete(kind,id){if(!myAllowWrite())return;const map={directive:data.directives,meeting:data.meetings,dim:data.dims},arr=map[kind],pos=arr.findIndex(x=>x.id===id);if(pos<0)return;if(!myAllowWrite(arr[pos]))return;if(!confirm('Hapus catatan ini? Tindakan tidak dapat dibatalkan tanpa cadangan.'))return;wfAudit(kind,'Dihapus',arr[pos]);arr.splice(pos,1);if(Array.isArray(data.lifecycle)){const removed=data.lifecycle.filter(x=>x.sourceKind===kind&&x.sourceId===id);data.lifecycle=data.lifecycle.filter(x=>!(x.sourceKind===kind&&x.sourceId===id));for(const row of removed)await lcLog('SOURCE_REMOVED',row.id,kind+':'+id);}await queueSave();render();}
function wfEscIcs(s){return String(s??'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');}
function wfUtc(t){return new Date(t).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');}
function wfCalendar(){const items=wfAllDeadlines();if(!items.length)return toast('Belum ada tenggat untuk diekspor.',true);const now=wfUtc(new Date());let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//SIPETAK//Pengingat Privat//ID','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:Pengingat SIPETAK'];for(const r of items){lines.push('BEGIN:VEVENT','UID:'+wfEscIcs(r.id)+'@sipetak','DTSTAMP:'+now,'DTSTART:'+wfUtc(r.dueAt),'DTEND:'+wfUtc(wfFuture(r.dueAt,15)),'SUMMARY:Pengingat pekerjaan SIPETAK','DESCRIPTION:Periksa daftar tenggat pada aplikasi SIPETAK. Judul pekerjaan tidak dimasukkan demi privasi.','CLASS:PRIVATE');for(const d of [1440,180,30,0]){lines.push('BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:Periksa tenggat pekerjaan SIPETAK','TRIGGER:-PT'+d+'M','END:VALARM')}lines.push('END:VEVENT')};lines.push('END:VCALENDAR');blobDownload('SIPETAK-Kalender-Privat-'+today()+'.ics',lines.join('\r\n')+'\r\n','text/calendar;charset=utf-8');toast('Kalender .ics dibuat. Impor file agar alarm bekerja melalui Kalender.');}
function wfCsv(name,headers,rows){const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';blobDownload(name,'\ufeff'+[headers,...rows].map(row=>row.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function wfExportDims(){wfCsv('SIPETAK-Matriks-DIM-'+myActiveYear()+'.csv',['Raperda','Pasal','Judul','Rumusan','Masalah','Usulan','Dasar Hukum','Hasil','Status','Tenggat'],myItems('dims').map(d=>[d.perda,d.article,d.title,d.current,d.issue,d.proposal,d.law,d.result,d.status,d.dueAt]));}
function wfPrintDims(){const body='<h1>Matriks DIM — Konsep Pribadi</h1><p>Periksa dan verifikasi seluruh rumusan dengan dokumen resmi.</p><table><thead><tr><th>Raperda/Pasal</th><th>Masalah</th><th>Usulan</th><th>Status</th></tr></thead><tbody>'+myItems('dims').map(x=>`<tr><td>${txt(x.perda)}<br>${txt(x.article)}</td><td>${txt(x.issue)}</td><td>${txt(x.proposal)}</td><td>${txt(x.status)}</td></tr>`).join('')+'</tbody></table>';documentPrint('Matriks DIM',body);}
function wfPrintMinutes(id){const x=data.meetings.find(r=>r.id===id);if(!x)return;documentPrint('Konsep Berita Acara Rapat',`<h1>CATATAN / KONSEP RISALAH RAPAT</h1><p><b>Agenda:</b> ${txt(x.title)}<br><b>Jenis:</b> ${txt(x.type)}<br><b>Waktu:</b> ${wfFormat(x.meetingAt)}<br><b>Lokasi:</b> ${txt(x.place)}<br><b>Dasar:</b> ${txt(x.source)}</p><h2>Bahan dan ringkasan pembahasan</h2><p>${txt(x.materials)}</p><h2>Rumusan hasil</h2><p>${txt(x.result)}</p><h2>Tindak lanjut</h2><p>${txt(x.followup)}</p><p><b>STATUS: KONSEP / BUKAN DOKUMEN DISAHKAN</b></p>`);}
function wfBrief(id){const x=data.directives.find(r=>r.id===id);if(!x)return;const lines=[['Arah/agenda',x.title],['Dasar arahan',x.source],['Batas waktu',wfFormat(x.dueAt)],['Pihak koordinasi',x.person],['Bahan/hasil yang tersedia',x.output],['Hal yang perlu ditindaklanjuti',x.notes]];documentPrint('Bahan Briefing Sekwan',`<h1>RINGKASAN BRIEFING SEKWAN — KONSEP</h1><p>Disusun dari isian Anda, bukan AI generatif dan bukan persetujuan pimpinan.</p>${lines.map(([h,v])=>`<h2>${txt(h)}</h2><p>${txt(v||'—')}</p>`).join('')}`);}
function wfSlaModal(){const content='<div class="callout warn">Nilai-nilai berikut <b>usulan internal</b>, bukan batas hukum. Perhitungan hanya Senin–Jumat 08.00–16.00 dan tidak menghitung hari libur.</div><div class="form-grid">'+Object.entries(WF_SLA_DEFAULTS).map(([name,obj],i)=>field(name+' (jam kerja)','rule'+i,'number',String(data.wfSettings.slaRules[name]??obj.hours),'',true,false,'min="1" max="240" step="1"')).join('')+'</div>';openModal('Ubah SLA internal','SLA diterapkan sebagai saran saat menambah pekerjaan, bukan mengubah tenggat yang sudah disimpan.',content,null,'wfSlaForm');$('wfSlaForm').addEventListener('submit',async e=>{e.preventDefault();Object.keys(WF_SLA_DEFAULTS).forEach((name,i)=>{const v=Number(e.currentTarget.elements['rule'+i].value);if(Number.isFinite(v)&&v>=1&&v<=240)data.wfSettings.slaRules[name]=v;});await queueSave();closeModal();render();toast('SLA internal diperbarui.');});}
function wfAudioUnlock(){const C=window.AudioContext||window.webkitAudioContext;if(!C)throw Error('Audio API tidak tersedia.');if(!wfAudio)wfAudio=new C();wfSoundReady=true;return wfAudio.resume();}
function wfBeep(){if(!wfAudio||wfAudio.state!=='running')return;try{const oscillator=wfAudio.createOscillator(),gain=wfAudio.createGain();oscillator.type='sine';oscillator.frequency.setValueAtTime(880,wfAudio.currentTime);oscillator.frequency.setValueAtTime(660,wfAudio.currentTime+.16);gain.gain.setValueAtTime(.001,wfAudio.currentTime);gain.gain.exponentialRampToValueAtTime(.13,wfAudio.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.001,wfAudio.currentTime+.5);oscillator.connect(gain);gain.connect(wfAudio.destination);oscillator.start();oscillator.stop(wfAudio.currentTime+.52);}catch(e){console.warn('Bunyi:',e.message)}}
async function wfEnableNotify(){try{await wfAudioUnlock();wfBeep();data.wfSettings.notify.sound=true;let permission='not-supported';if('Notification'in window&&window.isSecureContext){permission=await Notification.requestPermission();data.wfSettings.notify.system=permission==='granted';}await queueSave();render();toast(permission==='granted'?'Bunyi & izin notifikasi aktif selama aplikasi berjalan.':'Bunyi lokal aktif; notifikasi sistem tidak diizinkan/didukung.')}catch(e){fail(e)}}
async function wfLocalNotify(title,body,tag){try{if(!('Notification'in window)||Notification.permission!=='granted')return;const reg=await navigator.serviceWorker?.ready;if(reg?.showNotification)await reg.showNotification(title,{body,tag,icon:'./icons/icon-192.png'});else if(!('ontouchstart'in window))new Notification(title,{body,tag});}catch(e){console.warn('Notifikasi lokal:',e.message)}}
function wfReminderList(){const rows=[];for(const x of wfAllDeadlines()){const deadline=Date.parse(x.dueAt);for(const n of [1440,180,30,0])rows.push({id:x.id+':'+n,at:deadline-n*60000,alarmId:x.id,label:n===0?'Jatuh tempo':n+' menit sebelum tenggat',kind:x.kind});}return rows;}
async function wfTick(){if(!data||!vaultKey)return;const now=Date.now();const fired=new Set(data.notifyHistory.map(x=>x.id));const recent=wfReminderList().filter(x=>x.at<=now&&now-x.at<=3*60000&&!fired.has(x.id));if(!recent.length)return;for(const r of recent){data.notifyHistory.push({id:r.id,at:isoNow()});if(data.wfSettings.notify.sound&&wfSoundReady)wfBeep();if(data.wfSettings.notify.system)await wfLocalNotify('Pengingat SIPETAK','Ada pekerjaan yang mendekati atau mencapai tenggat. Buka SIPETAK untuk rinciannya.',r.id);}if(data.notifyHistory.length>2000)data.notifyHistory=data.notifyHistory.slice(-1200);await queueSave();if(view==='dashboard'||view==='sla')render();}
function startWorkflowLoop(){stopWorkflowLoop();wfTimer=setInterval(()=>{if(data&&vaultKey)wfTick().catch(console.warn)},30000);wfCloudTimer=setInterval(()=>{if(data&&vaultKey&&navigator.onLine&&data.wfSettings?.cloud?.auto&&Date.now()-wfLastSyncTime>120000)wfRunSync('auto').catch(console.warn)},120000);wfTick().catch(console.warn);}
function stopWorkflowLoop(){clearInterval(wfTimer);clearInterval(wfCloudTimer);wfTimer=null;wfCloudTimer=null;wfAudio?.suspend?.().catch(()=>{});wfSoundReady=false;}
let wfSaveSyncTimer=null;function workflowSaved(){if(!data?.wfSettings?.cloud?.auto||!data.wfSettings.cloud.url||!data.wfSettings.cloud.token||wfSyncRunning)return;clearTimeout(wfSaveSyncTimer);wfSaveSyncTimer=setTimeout(()=>{if(data&&vaultKey&&navigator.onLine)wfRunSync('auto').catch(console.warn)},5000);}
function wfCipherSig(e){return (e?.ciphertext||'').slice(0,90)+'/'+(e?.ciphertext?.length||0)}
function wfCipherKey(){try{return 'sipetak-last-cipher:'+new URL(data.wfSettings.cloud.url).origin}catch{return 'sipetak-last-cipher'}}
function wfCipherSeen(e){try{return localStorage.getItem(wfCipherKey())===wfCipherSig(e)}catch{return false}}
function wfMarkCipher(e){try{localStorage.setItem(wfCipherKey(),wfCipherSig(e))}catch{}}
function wfCleanUrl(base){const s=String(base||'').trim().replace(/\/+$/,'');const u=new URL(s);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error('Gunakan HTTPS atau localhost untuk uji lokal.');if(u.username||u.password)throw Error('Alamat URL tidak boleh mengandung kredensial.');return u.origin+u.pathname.replace(/\/$/,'');}
function wfCloudParams(){const c=data.wfSettings.cloud;if(!c.url||!c.token||c.token.length<20)throw Error('Isi URL dan token akses minimal 20 karakter pada menu Sinkronisasi.');return {url:wfCleanUrl(c.url),token:c.token,deviceId:c.deviceId};}
async function wfApi(path,method='GET',payload=null){const {url,token}=wfCloudParams();const resp=await fetch(url+path,{method,headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json'},body:payload===null?undefined:JSON.stringify(payload),cache:'no-store'});const j=await resp.json().catch(()=>({error:'Respons server bukan JSON.'}));if(!resp.ok)throw Error(j.error||'Server HTTP '+resp.status);return j;}
function wfSyncVersionKey(){return 'sipetak-sync-version:'+new URL(data.wfSettings.cloud.url).origin;}
function wfLocalVersion(){try{return Number(localStorage.getItem(wfSyncVersionKey())||0)}catch{return 0}}
function wfSaveLocalVersion(v){try{localStorage.setItem(wfSyncVersionKey(),String(v))}catch{}}
async function wfRunSync(direction){if(direction==='auto'&&!data?.wfSettings?.cloud?.auto)return;if(wfSyncRunning)return toast('Sinkronisasi sedang berjalan.',true);wfSyncRunning=true;try{await lastWrite;const status=await wfApi('/api/sync','GET');if(direction==='status'){toast('Versi server '+status.version+' · penyimpanan '+(status.hasData?'tersedia':'kosong'));return}let local=wfLocalVersion();if(direction==='auto'&&status.hasData&&status.version===local){const envelopeNow=await getEnvelope();if(wfCipherSeen(envelopeNow))return;}if(direction==='pull'){if(!status.hasData)throw Error('Belum ada data pada server. Kirim dari MacBook dahulu.');if(!confirm('Ambil data server dan GANTI seluruh data perangkat ini? Cadangkan perangkat terlebih dahulu.'))return;const remote=await wfApi('/api/sync/vault');wfPullModal(remote);return}
 if(status.hasData&&status.version!==local){throw Error('Konflik versi: server v'+status.version+', perangkat v'+local+'. Jangan timpa. Cadangkan data dan ambil dari server bila yakin.');}
 const envelope=await getEnvelope();const sent=await wfApi('/api/sync','PUT',{expected:status.version,vault:envelope});wfSaveLocalVersion(sent.version);wfMarkCipher(envelope);data.wfSettings.cloud.lastSync=isoNow();wfLastSyncTime=Date.now();toast('Brankas terenkripsi dikirim: server versi '+sent.version);if(data.wfSettings.cloud.push)await wfUploadPushSchedule(false);
 }catch(e){fail(e)}finally{wfSyncRunning=false}}
async function wfCloudSubmit(e){e.preventDefault();const v=formValue(e.currentTarget);try{const url=wfCleanUrl(v.url);if(String(v.token).trim().length<20)throw Error('Token minimal 20 karakter.');const old=data.wfSettings.cloud.url;data.wfSettings.cloud={...data.wfSettings.cloud,url,token:v.token.trim(),auto:Boolean(e.currentTarget.elements.auto.checked)};if(old!==url){try{localStorage.removeItem(wfSyncVersionKey())}catch{}}await queueSave();render();toast('Konfigurasi koneksi disimpan terenkripsi.');}catch(ex){fail(ex)}}
function wfB64ToUint(str){const raw=atob(str.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0));}
async function wfPushSubscribe(){try{if(!window.isSecureContext||!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('Perlu HTTPS dan browser yang mendukung Web Push. Di iPhone, gunakan aplikasi dari Layar Utama.');if(!('Notification'in window))throw Error('Notifikasi tidak tersedia.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Izin notifikasi tidak diberikan.');const reg=await navigator.serviceWorker.ready;const conf=await wfApi('/api/push/key');let subscription=await reg.pushManager.getSubscription();if(!subscription)subscription=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:wfB64ToUint(conf.publicKey)});await wfApi('/api/push/register','POST',{deviceId:data.wfSettings.cloud.deviceId,subscription:subscription.toJSON()});data.wfSettings.cloud.push=true;await queueSave();await wfUploadPushSchedule(false);toast('Perangkat terdaftar untuk push. Uji setelah server dipasang.');}catch(e){fail(e)}}
async function wfUploadPushSchedule(notify=true){const c=data.wfSettings.cloud;if(!c.push)throw Error('Aktifkan push perangkat ini terlebih dahulu.');const now=Date.now();const alarms=wfReminderList().filter(x=>x.at>now&&x.at<now+366*86400000).slice(0,3000).map(x=>({id:x.id,at:x.at}));const res=await wfApi('/api/push/schedule','PUT',{deviceId:c.deviceId,alarms});if(notify)toast('Server menerima '+res.count+' jadwal pengingat anonim.');}
async function wfPushUnregister(){try{const c=data.wfSettings.cloud;await wfApi('/api/push/register?deviceId='+encodeURIComponent(c.deviceId),'DELETE');const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription();if(sub)await sub.unsubscribe();c.push=false;await queueSave();render();toast('Pengingat server dinonaktifkan untuk perangkat ini.');}catch(e){fail(e)}}
function handleWorkflowClick(el){const act=el.dataset.action;if(!act?.startsWith('wf-'))return false;try{const id=el.dataset.id,kind=el.dataset.kind;if(act==='wf-new'||act==='wf-edit')wfModal(kind,id);if(act==='wf-delete')wfDelete(kind,id).catch(fail);if(act==='wf-calendar')wfCalendar();if(act==='wf-dimcsv')wfExportDims();if(act==='wf-dimprint')wfPrintDims();if(act==='wf-minutes')wfPrintMinutes(id);if(act==='wf-brief')wfBrief(id);if(act==='wf-edit-sla')wfSlaModal();if(act==='wf-enable-notify')wfEnableNotify().catch(fail);if(act==='wf-test-sound'){wfAudioUnlock().then(()=>{wfBeep();toast('Bunyi diuji. Pastikan volume perangkat tidak senyap.')}).catch(fail)}if(act==='wf-sync-push')wfRunSync('push').catch(fail);if(act==='wf-sync-pull')wfRunSync('pull').catch(fail);if(act==='wf-sync-status')wfRunSync('status').catch(fail);if(act==='wf-push-register')wfPushSubscribe().catch(fail);if(act==='wf-push-update')wfUploadPushSchedule().catch(fail);if(act==='wf-push-unregister')wfPushUnregister().catch(fail);}catch(e){fail(e)}return true;}
document.addEventListener('submit',e=>{if(e.target?.id==='wfCloudForm'){e.preventDefault();wfCloudSubmit(e).catch(fail)}},true);
/* Optional legal reference library; records title/metadata, not full protected text. */
function pustakaPage(){const rows=data.laws||[];return `<div class="section-head"><div><h3>Referensi hukum & dokumen rujukan</h3><p>Catat asal, nomor, pasal, status verifikasi dan rujukan arsip resmi.</p></div><button class="btn" data-action="wf-law-new">＋ Tambah Referensi</button></div><div class="callout warn">Sumber awal: Peraturan DPRD No. 1/2024 (Tata Tertib), Perbup No. 57/2021 dan <b>Rancangan Akhir</b> Renstra 2025–2029. Verifikasi perubahan/pencabutan dan versi final di JDIH atau arsip instansi sebelum menjadikannya dasar keputusan.</div><div class="wf-cards">${rows.length?rows.map(x=>`<article class="card"><div class="tiny muted">${txt(x.type||'Peraturan')} · ${txt(x.status||'Perlu verifikasi')}</div><h3>${txt(x.title)}</h3><p class="hint"><b>Nomor/Tahun:</b> ${txt(x.number||'—')} / ${txt(x.year||'—')}<br><b>Pasal:</b> ${txt(x.article||'—')}<br><b>Sumber:</b> ${txt(x.origin||'—')}<br><b>Diperiksa:</b> ${fmtDate(x.verifiedAt)}</p><p>${txt(x.notes||'').slice(0,230)}</p><div class="actions"><button class="btn sm secondary" data-action="wf-law-edit" data-id="${txt(x.id)}">Ubah</button><button class="btn sm danger" data-action="wf-law-delete" data-id="${txt(x.id)}">Hapus</button></div></article>`).join(''):blank('Belum ada pustaka pribadi. Tambahkan referensi dan lokasi arsip resmi.','▧')}</div>`;}
function wfLawModal(id){const x=data.laws.find(t=>t.id===id)||{};const body=`<div class="form-grid">${field('Judul dokumen / peraturan','title','text',x.title||'','Judul lengkap',true,true)}${field('Jenis referensi','type','select','','',false,false,wfCategorySelect(['Peraturan DPRD','Peraturan Bupati','Renstra','Keputusan DPRD','Undang-Undang','Peraturan Menteri','Lainnya'],x.type||'Peraturan DPRD'))}${field('Nomor','number','text',x.number||'')}${field('Tahun','year','number',x.year||'','',false,false,'min="1945" max="2100"')}${field('Pasal / bagian relevan','article','text',x.article||'','Contoh: Pasal 12',false,true)}${field('Status verifikasi','status','select','','',false,false,wfCategorySelect(['Perlu verifikasi','Telah diverifikasi internal','Rancangan / belum final','Tidak berlaku / arsip'],x.status||'Perlu verifikasi'))}${field('Tanggal periksa','verifiedAt','date',x.verifiedAt||today())}${field('Sumber resmi / lokasi dokumen','origin','text',x.origin||'','JDIH, SRIKANDI, atau arsip fisik',false,true)}${field('Catatan perubahan, relevansi, atau risiko','notes','textarea',x.notes||'','Periksa status terbaru sebelum dikutip',false,true)}</div>`;openModal('Referensi Hukum','Bibliografi dan status, tanpa pengesahan hukum otomatis.',body,null,'wfLawForm');$('wfLawForm').dataset.id=id||'';$('wfLawForm').addEventListener('submit',async e=>{e.preventDefault();const r=formValue(e.currentTarget),old=data.laws.find(t=>t.id===id),row={...old,...r,id:old?.id||uid('LAW'),createdAt:old?.createdAt||isoNow(),updatedAt:isoNow()};if(old)Object.assign(old,row);else data.laws.push(row);wfAudit('pustaka',old?'Diperbarui':'Dibuat',row);await queueSave();closeModal();render();toast('Referensi tersimpan.')})}
async function wfLawDelete(id){const i=data.laws.findIndex(x=>x.id===id);if(i<0||!confirm('Hapus referensi ini?'))return;wfAudit('pustaka','Dihapus',data.laws[i]);data.laws.splice(i,1);await queueSave();render();}
function asistenPage(){const active=wfAllDeadlines(),pending=active.filter(x=>Date.parse(x.dueAt)<Date.now()+86400000),reviews=data.reviews.filter(x=>!x.law||!x.facts||!x.recommendation),meeting=data.meetings.filter(x=>x.prepStatus!=='Selesai');return `<div class="section-head"><div><h3>Pemeriksa kelengkapan & pembuat kerangka</h3><p>Asisten lokal berbasis aturan, bukan AI generatif atau penilaian hukum otomatis.</p></div><button class="btn" data-action="wf-draft-report">Cetak daftar prioritas</button></div><div class="wf-summary"><div><strong>${pending.length}</strong><small>Tenggat ≤24 jam/terlewat</small></div><div><strong>${reviews.length}</strong><small>Telaahan belum lengkap</small></div><div><strong>${meeting.length}</strong><small>Bahan rapat belum selesai</small></div></div><div class="split2"><section class="card"><h3>Daftar periksa telaahan</h3>${data.reviews.length?data.reviews.map(x=>{const needed=[['Fakta dan sumber',x.facts],['Dasar hukum dan pasal',x.law],['Analisis',x.analysis],['Alternatif',x.alternatives],['Rekomendasi',x.recommendation]];return `<div class="wf-check-row"><b>${txt(x.title)}</b><div class="tiny muted">${needed.filter(v=>v[1]).length}/${needed.length} unsur terisi · ${txt(needed.filter(v=>!v[1]).map(v=>v[0]).join(', ')||'Semua unsur sudah terisi (belum berarti valid)')}</div></div>`}).join(''):blank('Belum ada telaahan untuk diperiksa.','✧')}</section><section class="card"><h3>Catatan otomatis untuk briefing</h3><p class="hint">Dihasilkan dari data penugasan yang Anda isi. Gunakan tombol Briefing di menu Asisten Sekwan untuk menyusun konsep laporan per penugasan.</p><h4>Tenggat mendesak</h4>${pending.slice(0,7).map(x=>`<p class="hint">◷ ${wfFormat(x.dueAt)} · ${txt(x.title)}</p>`).join('')||'<p class="hint">Tidak ada pekerjaan mendesak yang tercatat.</p>'}<div class="callout warn">Aplikasi tidak memeriksa keberlakuan hukum dan tidak boleh menghasilkan keputusan otomatis. AI berbasis layanan eksternal belum diaktifkan karena memerlukan persetujuan kebijakan data dan penyedia layanan.</div></section></div><section class="card"><h3>Riwayat aktivitas dalam brankas lokal</h3><p class="hint">Catatan ini bersifat lokal dan dapat diubah oleh pemilik perangkat; <b>bukan jejak audit tersertifikasi</b>.</p><div class="wf-scroll">${data.audit.length?data.audit.slice(0,30).map(x=>`<div class="wf-deadline"><div><b>${txt(x.action)} · ${txt(x.type)}</b><p>${wfFormat(x.at)} · ${txt(x.title)}</p></div></div>`).join(''):blank('Belum ada riwayat perubahan.','✧')}</div></section>`;}
function wfReportSupplement(){const ts=myItems('tasks').filter(x=>x.date?.startsWith(reportMonth)),d=myItems('directives').filter(x=>x.receivedAt?.startsWith(reportMonth)),m=myItems('meetings').filter(x=>x.meetingAt?.startsWith(reportMonth)),dim=myItems('dims').filter(x=>x.dueAt?.startsWith(reportMonth));return `<section class="card wf-focus"><div class="section-head"><div><h3>Hasil kerja lintas dua peran</h3><p>Periode ${txt(reportMonth)} · status bersumber dari isian pengguna</p></div><button class="btn sm secondary" data-action="wf-report-csv">↓ Rekap lengkap CSV</button></div><div class="wf-summary"><div><strong>${ts.length}</strong><small>Tugas</small></div><div><strong>${d.length}</strong><small>Disposisi / agenda</small></div><div><strong>${m.length+dim.length}</strong><small>Rapat dan DIM</small></div></div><p class="hint">Capaian organisasi tidak otomatis diturunkan dari jumlah kegiatan. Perlu verifikasi atasan dan formula IKI yang disepakati.</p></section>`;}
function wfExportAll(){const r=[...myItems('tasks').map(x=>[x.date,'Tugas',x.title,x.status,x.output,x.deadlineAt||x.deadline,x.rhkId]),...myItems('directives').map(x=>[x.receivedAt,'Asisten Sekwan',x.title,x.status,x.output,x.dueAt,x.rhkId]),...myItems('meetings').map(x=>[x.meetingAt,'Persidangan',x.title,x.minutesStatus,x.result,x.minutesDueAt,x.rhkId]),...myItems('dims').map(x=>[x.dueAt,'DIM',x.title,x.status,x.result,x.dueAt,x.rhkId])].filter(x=>String(x[0]||'').startsWith(reportMonth));wfCsv('SIPETAK-Rekap-Lintas-Peran-'+reportMonth+'.csv',['Tanggal','Jenis','Pekerjaan','Status','Hasil','Tenggat','RHK'],r)}
function wfDraftReport(){const deadlines=wfActiveDeadlines().slice(0,30);const html='<h1>DAFTAR PRIORITAS PEKERJAAN — KONSEP</h1><p>Disusun dari data SIPETAK pada '+txt(new Date().toLocaleString('id-ID'))+'. Bukan instruksi atau keputusan pejabat.</p><table><thead><tr><th>Pekerjaan</th><th>Tenggat</th><th>Status SLA</th></tr></thead><tbody>'+deadlines.map(x=>`<tr><td>${txt(x.title)}</td><td>${wfFormat(x.dueAt)}</td><td>${txt(wfSlaState(x).label)}</td></tr>`).join('')+'</tbody></table>';documentPrint('Daftar Prioritas',html)}
const wfOldAction=handleWorkflowClick;
handleWorkflowClick=function(el){const act=el.dataset.action;if(!act?.startsWith('wf-'))return false;
 if(act==='wf-mobile-menu'){wfMobileMenu();return true}if(act==='wf-law-new'){wfLawModal('');return true}if(act==='wf-law-edit'){wfLawModal(el.dataset.id);return true}if(act==='wf-law-delete'){wfLawDelete(el.dataset.id).catch(fail);return true}if(act==='wf-report-csv'){wfExportAll();return true}if(act==='wf-draft-report'){wfDraftReport();return true}return wfOldAction(el)};

function wfMobileMenu(){const body=`<div class="wf-menu-grid">${VIEWS.map(v=>`<button class="btn ghost wf-menu-button" type="button" data-action="navigate" data-view="${v[0]}">${v[1]} ${txt(v[2])}</button>`).join('')}</div>`;openModal('Semua Menu SIPETAK','Akses seluruh modul pada iPhone.',body,'<button type="button" class="btn ghost" data-action="close">Tutup</button>','wfMenuForm');}

function wfCompletionRate(){const done=[];for(const x of myItems('tasks')){const due=x.deadlineAt||(x.deadline?x.deadline+'T16:00':null);if(x.status==='Selesai'&&due&&x.completedAt)done.push([x.completedAt,due]);}for(const x of data.directives){if(x.status==='Selesai'&&x.dueAt&&x.completedAt)done.push([x.completedAt,x.dueAt]);}for(const x of data.meetings){if(x.prepStatus==='Selesai'&&x.prepDueAt&&x.prepCompletedAt)done.push([x.prepCompletedAt,x.prepDueAt]);if(x.minutesStatus==='Selesai'&&x.minutesDueAt&&x.minutesCompletedAt)done.push([x.minutesCompletedAt,x.minutesDueAt]);}for(const x of data.dims){if(x.status==='Selesai'&&x.dueAt&&x.completedAt)done.push([x.completedAt,x.dueAt]);}const onTime=done.filter(([when,due])=>Date.parse(when)<=Date.parse(due)).length;return {done:done.length,onTime,pct:done.length?Math.round(100*onTime/done.length):0};}

function wfPullModal(remote){openModal('Pulihkan data terenkripsi dari server','Ganti semua data lokal dengan versi yang dipilih.',`<div class="callout critical">Pemulihan ini mengganti semua data dan tidak menggabungkan konflik. Buat cadangan sebelum melanjutkan.</div><div class="form-grid">${field('Kata sandi brankas perangkat asal','vaultPassword','password','','Kata sandi dari perangkat yang pertama kali mengirim data',true,true)}</div>`,null,'wfPullForm');$('wfPullForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('[type=submit]');btn.disabled=true;try{const pw=e.currentTarget.elements.vaultPassword.value;if(pw.length<10)throw Error('Kata sandi minimal 10 karakter.');const key=await makeKey(pw,bytesFromB64(remote.vault.salt),remote.vault.iterations);const restored=await decryptVault(remote.vault,key);await lastWrite;await putEnvelope(remote.vault);vaultEnvelope=remote.vault;vaultKey=key;data=restored;ensureWorkflow();wfSaveLocalVersion(remote.version);wfMarkCipher(remote.vault);closeModal();renderNav();render();toast('Data server dipulihkan. Buat cadangan baru.');}catch(ex){fail(ex);btn.disabled=false;}})}
